hl.config({
    ecosystem = {
        no_update_news = true,
        no_donation_nag = true,
    },
})

-- See: https://github.com/ChrisTitusTech/hyprland-titus/blob/main/dotconfig/hypr/hyprland.conf
-- source ~/.config/hypr/monitor.conf

-- Unscale XWayland
hl.config({
    xwayland = {
        force_zero_scaling = true,
    },
})

-- toolkit-specific scale
hl.env("XCURSOR_SIZE", 24)
hl.env("HYPRCURSOR_SIZE", 24)

-- GTK Fixes
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("GDK_SCALE", 1)
--env = GTK_THEME=Adwaita:dark

-- QT fixes
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_SCALE_FACTOR_ROUNDING_POLICY", "RoundPreferFloor")
--env = QT_WAYLAND_DISABLE_WINDOWDECORATION,1
--env = QT_AUTO_SCREEN_SCALE_FACTOR,1

-- Anki fixes
-- package:anki
hl.env("ANKI_WAYLAND", 1)
hl.env("ANKI_WEBSCALE", 0.75)

-- Miscellaneous fixes
-- Set to x11 if games that provide older versions of SDL cause compatibility issues
hl.env("SDL_VIDEODRIVER", "wayland")
hl.env("CLUTTER_BACKEND", "wayland")

-- NOTE: It seems GTK_IM_MODULE, QT_IM_MODULE and SDL_IM_MODULE should not be set; see
--       https://forum.endeavouros.com/t/fcitx-wayland-diagnose/47481/2
hl.env("XMODIFIERS", "@im=fcitx")
-- Some SDL games:
hl.env("SDL_IM_MODULE", "fcitx")
-- In order for kitty to work:
hl.env("GLFW_IM_MODULE", "ibus")


-- NOTE: These have been moved to .xprofile to only be used in xwayland applications.
--env = GTK_IM_MODULE,fcitx
--env = QT_IM_MODULE,fcitx

-- == fix: Mpv gamut bug ==
--windowrule = content none, match:class mpv

-- Autostart
hl.on("hyprland.start", function()
    -- Monitor configuration
    -- package:kanshi
    -- exec-once = kanshi
    -- exec-once = ~/.config/hypr/scripts/monitor-config.sh

    -- Waybar
    -- package:waybar
    hl.exec_cmd("waybar")

    -- RAM usage notification
    hl.exec_cmd("~/.config/hypr/scripts/ram-monitor.sh")

    -- Notification daemon
    -- package:mako
    hl.exec_cmd("mako")

    -- Power notifications
    -- package:poweralertd
    hl.exec_cmd("poweralertd")

    -- package:polkit-gnome
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")

    -- `--disable notificationitem` is in order to disable the tray item as the icons is ugly
    -- package:fcitx5-im
    hl.exec_cmd("fcitx5 --disable notificationitem")

    -- Wallpaper
    -- package:awww
    hl.exec_cmd("awww-daemon")
end)

