-- See https://wiki.hyprland.org/Configuring/Keywords/ for more

-- ALT / SUPER
local mod = "SUPER"

-- package:aur/tofi
local menu = "tofi-drun --drun-launch=true"
--$menu = wofi --show=drun

hl.bind(mod .. " + " .. "B", hl.dsp.exec_cmd("pkill -SIGUSR1 waybar"))

-- Example binds, see https://wiki.hyprland.org/Configuring/Binds/ for more
-- Syntax:
--   bind = <MODS>, <key>, <dispatcher>, <params>

hl.bind(mod .. " + " .. "RETURN", hl.dsp.exec_cmd("kitty"))

-- package:kitty
-- popup terminal:
hl.bind(mod .. " + " .. "T", hl.dsp.exec_cmd("kitty --class=kitty-popup"))

hl.bind(mod .. " + " .. "D", hl.dsp.exec_cmd("tofi-drun --drun-launch=true"))
hl.bind(mod .. " + " .. "M", hl.dsp.exec_cmd("~/.config/hypr/scripts/random-wallpaper.sh"))

-- --transition-duration 0.5 :
hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "M", hl.dsp.exec_cmd("awww img ~/Wallpapers/blood-moon.png"))

hl.bind(mod .. " + " .. "Q", hl.dsp.window.close())
hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "Q", hl.dsp.window.kill())
hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "E", hl.dsp.exit())
--bind = $mod, F, exec, dolphin
hl.bind(mod .. " + " .. "V", hl.dsp.window.float())
--bind = $mod, P, pseudo, # dwindle
--bind = $mod, J, togglesplit, # dwindle
hl.bind(mod .. " + " .. "F", hl.dsp.window.fullscreen())

-- Move focus with mod + arrow keys
hl.bind(mod .. " + " .. "H", hl.dsp.focus({ direction = "left" }))
hl.bind(mod .. " + " .. "J", hl.dsp.focus({ direction = "down" }))
hl.bind(mod .. " + " .. "K", hl.dsp.focus({ direction = "up" }))
hl.bind(mod .. " + " .. "L", hl.dsp.focus({ direction = "right" }))

-- Resize with mod + ctrl + arrow keys

-- TODO: https://www.reddit.com/r/hyprland/comments/1tbmon2/how_to_convert_resize_percentage_to_lua/

hl.bind(mod .. " + CTRL + H", hl.dsp.window.resize({ x = -20, y = 0, relative = true, window = "activewindow" }))
hl.bind(mod .. " + CTRL + J", hl.dsp.window.resize({ x = 0, y = 20, relative = true, window = "activewindow" }))
hl.bind(mod .. " + CTRL + K", hl.dsp.window.resize({ x = 0, y = -20, relative = true, window = "activewindow" }))
hl.bind(mod .. " + CTRL + L", hl.dsp.window.resize({ x = 20, y = 0, relative = true, window = "activewindow" }))

-- Move with mod + shift + arrow keys

--hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "H", hl.dsp.window.move({ direction = "l" }))
hl.bind(mod .. " + SHIFT + H", hl.dsp.window.move({ direction = "l" }))
hl.bind(mod .. " + SHIFT + J", hl.dsp.window.move({ direction = "d" }))
hl.bind(mod .. " + SHIFT + K", hl.dsp.window.move({ direction = "u" }))
hl.bind(mod .. " + SHIFT + L", hl.dsp.window.move({ direction = "r" }))

-- Switch workspaces with mod + [0-9]

hl.bind(mod .. " + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind(mod .. " + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind(mod .. " + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind(mod .. " + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind(mod .. " + 5", hl.dsp.focus({ workspace = 5 }))
hl.bind(mod .. " + 6", hl.dsp.focus({ workspace = 6 }))
hl.bind(mod .. " + 7", hl.dsp.focus({ workspace = 7 }))
hl.bind(mod .. " + 8", hl.dsp.focus({ workspace = 8 }))
hl.bind(mod .. " + 9", hl.dsp.focus({ workspace = 9 }))
hl.bind(mod .. " + 0", hl.dsp.focus({ workspace = 10 }))

-- Move active window to a workspace with mod + SHIFT + [0-9]

hl.bind(mod .. " + SHIFT + 1", hl.dsp.window.move({ workspace = 1 }))
hl.bind(mod .. " + SHIFT + 2", hl.dsp.window.move({ workspace = 2 }))
hl.bind(mod .. " + SHIFT + 3", hl.dsp.window.move({ workspace = 3 }))
hl.bind(mod .. " + SHIFT + 4", hl.dsp.window.move({ workspace = 4 }))
hl.bind(mod .. " + SHIFT + 5", hl.dsp.window.move({ workspace = 5 }))
hl.bind(mod .. " + SHIFT + 6", hl.dsp.window.move({ workspace = 6 }))
hl.bind(mod .. " + SHIFT + 7", hl.dsp.window.move({ workspace = 7 }))
hl.bind(mod .. " + SHIFT + 8", hl.dsp.window.move({ workspace = 8 }))
hl.bind(mod .. " + SHIFT + 9", hl.dsp.window.move({ workspace = 9 }))
hl.bind(mod .. " + SHIFT + 0", hl.dsp.window.move({ workspace = 10 }))

-- Scroll through existing workspaces with mod + scroll
hl.bind(mod .. " + " .. "mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mod .. " + " .. "mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mod + LMB/RMB and dragging
hl.bind(mod .. " + " .. "mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mod .. " + " .. "mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Print-screen select (PrtSc button = `Print`)
-- package:grim package:slurp package:wl-clipboard
hl.bind(mod .. " + " .. "S", hl.dsp.exec_cmd("tmpfile=$(mktemp -p/tmp screenshot.XXXXXXXXXX) && grim -g \"$(slurp)\" \"$tmpfile\" && wl-copy -t image/png < \"$tmpfile\""))

-- Color picker
-- package:hyprpicker package:wl-clipboard
hl.bind(mod .. " + " .. "P", hl.dsp.exec_cmd("hyprpicker --autocopy"))

-- Hide waybar

-- Brightness
-- package:brightnessctl
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl -n --exponent=2 set +5% && notify-send -h string:x-canonical-private-synchronous:59404 'Ljusstyrka ökad' \"Ljusstyrka satt till $(brightnessctl g)/$(brightnessctl m)\""))
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -n --exponent=2 set 5%- && notify-send -h string:x-canonical-private-synchronous:59404 'Ljusstyrka minskad' \"Ljusstyrka satt till $(brightnessctl g)/$(brightnessctl m)\""))
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pulsemixer --change-volume +5 && notify-send -h string:x-canonical-private-synchronous:59404 'Volym ökad' \"Volym satt till $(pulsemixer --get-volume)\""))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pulsemixer --change-volume -5 && notify-send -h string:x-canonical-private-synchronous:59404 'Volym ökad' \"Volym satt till $(pulsemixer --get-volume)\""))

