    name = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})

-- "Fix some dragging issues with XWayland" (from the default config)
hl.window_rule({
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

